a = input()
if len(a) == 1:
	if int(a) % 3 == 0:
		print(a)
	else:
		print(-1)
	exit(0)
one = []
two = []
sum = 0
(zs, zf) = (0, 0)
for i in range(len(a)):
	q = int(a[i])
	sum += q
	if q == 0:
		if zs == 0:
			zs = i
	elif zs != 0 and zf == 0:
		zf = i
	if q % 3 == 1:
		if len(one) <= 4:
			one.append(i)
	elif q % 3 == 2:
		if len(two) <= 4:
			two.append(i)
if zf == 0 and zs != 0:
	zf = len(a) - 1
sol = []
s = ''
if sum % 3 == 1:
	if len(one) > 0:
		s = a[:one[-1]] + a[one[-1] + 1:]
		sol.append(s)
	if len(a) > 1 and len(two) > 1:
		s = a[:two[-2]] + a[two[-2] + 1:two[-1]] + a[two[-1] + 1:]
		sol.append(s)
if sum % 3 == 2:
	if len(two) > 0:
		s = a[:two[-1]] + a[two[-1] + 1:]
		sol.append(s)
	if len(a) > 1 and len(one) > 1:
		s = a[:one[-2]] + a[one[-2] + 1:one[-1]] + a[one[-1] + 1:]
		sol.append(s)
if sum % 3 == 0:
	print(a)
else:
	mini = 0
	max = 0
	for i in range(len(sol)):
		if sol[i] == '':
			sol[i] = '-1'
		elif sol[i][0] == '0':
			sol[i] = sol[i][zf - zs:]
			if len(sol[i]) > 0:
				if sol[i][0] == '0':
					f = -1
					for j in range(len(sol[i])):
						if sol[i][j] != '0':
							f = j
							break
					if f != -1:
						sol[i] = sol[i][f:]
					else:
						sol[i] = '0'
			if len(sol[i]) == 0:
				sol[i] = '0'
		if len(sol[i]) > max:
			max = len(sol[i])
			mini = i
	print(sol[mini])
